} as const;
const OSIO_SHOP = { key: "osio", name: "OSIO organic", url: "https://osio-organic.com.ua/" } as const;

function appWithFakeShops(source: DataSource, dir: string = snapshotDir) {
  const karashynyard = vi.fn<ShopAdapter["fetchProducts"]>();
