};
const hrechanyiChai: AdminProduct = {
  id: "karashynyard:1743423686258",
  shopKey: "karashynyard",
  shopName: "Карашин Яр",
  sourceId: "1743423686258",
  name: "Гречаний чай з жасмином 100 г (99 чашок)",
