      {alert !== undefined && (
        <p role="alert" className="mt-3 text-sm text-red-700">
          {alert}
        </p>
      )}
      <button type="button" onClick={() => void logout()} className="mt-6 rounded-md border border-stone-300 px-3 py-2 text-sm">
